#!/usr/bin/env bash
# Keeps one open release PR from develop to main whose description lists
# everything on develop that isn't on main yet, newest first.
# Needs: gh (GH_TOKEN), a clone with full history of both branches.
# DRY_RUN=1 prints the description instead of touching GitHub.
set -euo pipefail

BASE=${BASE:-main}
HEAD=${HEAD:-develop}
TITLE="Release: $HEAD → $BASE"
REPO=${GITHUB_REPOSITORY:-$(gh repo view --json nameWithOwner -q .nameWithOwner)}

git fetch --quiet origin "$BASE" "$HEAD"

# First-parent commits on develop that main doesn't have: one per merged PR
# (merge or squash) or per direct push.
commits=$(git rev-list --first-parent "origin/$BASE..origin/$HEAD")
if [ -z "$commits" ]; then
  echo "$HEAD and $BASE are the same: nothing to release."
  exit 0
fi

# Merged PRs into develop, keyed by their merge commit.
prs=$(gh pr list --repo "$REPO" --base "$HEAD" --state merged --limit 500 \
  --json number,title,author,url,mergeCommit \
  --jq '.[] | select(.mergeCommit) | [.mergeCommit.oid, (.number|tostring), .author.login, .url, .title] | @tsv')

lines=""
n_prs=0
n_commits=0
for sha in $commits; do
  pr=$(printf '%s\n' "$prs" | awk -F'\t' -v s="$sha" '$1 == s' | head -1)
  if [ -n "$pr" ]; then
    IFS=$'\t' read -r _ number login url title <<<"$pr"
    # Author as a link, not an @mention, so edits don't ping anyone.
    lines+="- [#$number]($url) $title, by [$login](https://github.com/$login)"$'\n'
    n_prs=$((n_prs + 1))
  else
    subject=$(git log -1 --format=%s "$sha")
    author=$(git log -1 --format=%an "$sha")
    lines+="- $(git rev-parse --short "$sha") $subject, by $author (direct push)"$'\n'
    n_commits=$((n_commits + 1))
  fi
done

count="**$n_prs PR(s)**"
[ "$n_commits" -gt 0 ] && count+=" and **$n_commits direct commit(s)**"

body="<!-- Generated by .github/workflows/release-pr.yml: edits are overwritten on the next push to $HEAD. -->
This PR is kept up to date automatically on every push to \`$HEAD\`.
Merge it with a **merge commit** (not squash or rebase), so \`$BASE\` and \`$HEAD\` keep a shared history and the next release lists only new work.

$count waiting to ship, newest first:

$lines"

if [ "${DRY_RUN:-}" = 1 ]; then
  printf '%s' "$body"
  exit 0
fi

existing=$(gh pr list --repo "$REPO" --base "$BASE" --head "$HEAD" --state open --json number --jq '.[0].number // empty')
if [ -n "$existing" ]; then
  gh pr edit "$existing" --repo "$REPO" --title "$TITLE" --body "$body"
  echo "Updated release PR #$existing"
else
  gh pr create --repo "$REPO" --base "$BASE" --head "$HEAD" --title "$TITLE" --body "$body"
fi
